import { renderToStaticMarkup } from 'react-dom/server';
import { describe, expect, it } from 'vitest';

import { StatusBadge } from '../status-badge.js';

/** The badge's tone, checked as static markup like the rest of the badge. */

describe('StatusBadge tone', () => {
  it('carries the tone it is given', () => {
    for (const tone of ['neutral', 'positive', 'warning', 'critical'] as const) {
      expect(renderToStaticMarkup(<StatusBadge status="passed" tone={tone} />)).toContain(`data-tone="${tone}"`);
    }
  });

  it('reads as neutral when no tone is given', () => {
    expect(renderToStaticMarkup(<StatusBadge status="failed" />)).toContain('data-tone="neutral"');
  });

  it('never changes the word the badge shows', () => {
    const markup = renderToStaticMarkup(<StatusBadge status="failed" tone="positive" />);

    expect(markup).toContain('Failed');
    expect(markup).toContain('data-status="failed"');
  });
});
